mapper.select:
select count(1)
from sys_layer
where
  delete_flag = 0
  and tenant_id = #{tenantId}
  and industry_code = #{industryCode}
  and custom_name = #{customName}
  AND category = #{category}

select count(1)
from sys_layer
where
    delete_flag = 0
  and tenant_id = #{tenantId}
  and industry_code = #{industryCode}
  and layer_type_id = #{layerTypeId}

select l.id, l.tenant_id tenantId, l.industry_code industryCode, l.geoserver_url geoserverUrl, l.view_url viewUrl, l.layer_name layerName, l.layer_namespace layerNamespace, l.app_ver_code appVerCode,
case when IFNULL(ar.id,0) = 0 then 0 else 1 end markFlag,
CASE WHEN SUBSTRING(l.custom_name, 1, 1) REGEXP '[一-龥]' THEN firstPinyin(l.custom_name) ELSE SUBSTRING(l.custom_name, 1, 1) END AS customNamePrd,
l.custom_name customName, l.creator, l.modifier, l.create_time createTime, l.update_time updateTime, lt.type_name layerTypeName, lt.abbreviation, ic.industry_name industryName, ti.tenant_name tenantName, l.game_key gameKey, l.maxx maxx, l.maxy maxy, l.minx minx, l.miny miny, l.root_geoserver_url rootGeoserverUrl, l.layer_type_id layerTypeId, l.polygon_count polygonCount, l.layer_area layerArea, l.category category, l.geo_type geoType, l.nest_flag nestFlag, l.file_url fileUrl, l.notes notes, l.obs_url obsUrl, l.file_name fileName, l.upload_type uploadType, l.publish_status publishStatus, l.origin_url originUrl from sys_layer l left join sys_layer_type lt on l.layer_type_id = lt.id left join sys_tenant_info ti on l.tenant_id = ti.tenant_id and ti.del_flag = 0 left join sys_industry_conf ic on ic.delete_flag = 0 and l.industry_code = ic.industry_code and ic.accept_node = #{acceptNode}
left join vm_ar_tags_user_rel ar on l.id = ar.tag_id and ar.user_id = #{dto.userName}
where l.delete_flag = 0
and l.id = #{dto.id}
and lt.id = #{dto.layerTypeId}
and l.category = #{dto.category}
and l.category = 1
and l.category IN
#{item}
and lt.abbreviation = #{dto.abbreviation}
and ic.industry_code = #{dto.industryCode}
and l.custom_name like concat('%',#{dto.customName},'%')
and l.creator like concat('%',#{dto.creator},'%')
and l.modifier like concat('%',#{dto.modifier},'%')
and l.tenant_id = #{dto.tenantId}
and l.create_time between #{dto.createBeginTime} and #{dto.createEndTime}
and l.update_time between #{dto.updateBeginTime} and #{dto.updateEndTime}
and l.nest_flag = #{dto.nestFlag}
and l.upload_type = #{dto.uploadType}
and l.publish_status = #{dto.publishStatus}
and (l.publish_status = '1' or l.publish_status is null)
${dto.dataPermissions}
ORDER BY IF(customNamePrd RLIKE '^[a-z]', 1, 2)
order by ${orderBy}
order by l.create_time desc

