mapper.update:
UPDATE sys_layer
SET nest_flag = #{nestFlag},modifier = #{username}, update_time = now()
WHERE id = #{id}

UPDATE sys_layer SET nest_flag = 1,update_time = now() WHERE id IN (SELECT tt.id from (SELECT t.* FROM (SELECT id, layer_type_id, create_time, ROW_NUMBER() OVER(PARTITION BY accept_node,tenant_id,industry_code,layer_type_id ORDER BY create_time asc) as rn FROM sys_layer WHERE delete_flag = 0 AND layer_type_id in
#{item}
ORDER BY accept_node, tenant_id, industry_code, layer_type_id, create_time asc) t where t.rn = 1) tt) AND tenant_id = #{tenantId} AND industry_code = #{industryCode};

mapper.select:
SELECT t1.layer_type_id, t2.type_name AS layerTypeName, cast( sum( t1.layer_area ) AS DECIMAL ( 19, 0 ) ) AS area FROM sys_layer t1, sys_layer_type t2 WHERE t1.layer_type_id = t2.id AND t1.delete_flag = 0 AND t2.delete_flag = 0
AND t2.id = #{layerTypeId}
AND t2.abbreviation = #{abbreviation}
${dataPermissions} GROUP BY t1.layer_type_id, t2.type_name

