mapper.select:
SELECT
    l.category,
    count( l.id ) as layerCount
FROM
    sys_layer l
    LEFT JOIN sys_layer_type lt on l.layer_type_id = lt.id
    LEFT JOIN sys_tenant_info ti on l.tenant_id = ti.tenant_id and ti.del_flag = 0
    LEFT JOIN sys_industry_conf ic on ic.delete_flag = 0 and l.industry_code = ic.industry_code and ic.accept_node = #{platformCode}
WHERE
    l.delete_flag = 0

        AND l.industry_code = #{industryCode}


        AND l.tenant_id = #{tenantId}


        AND l.category = #{category}


        AND (l.upload_type = '1' OR ( l.upload_type = '2' AND l.publish_status = '1' ))

${dataPermissions}
GROUP BY l.category
